"""Straightforward reference replay model (hop-by-hop simulation)."""


def ref_packet(flow, header_hex, payload_hex, enabled):
    header = bytes.fromhex(header_hex)
    payload = bytes.fromhex(payload_hex)
    kinds = flow['kinds']
    template = bytes.fromhex(flow['template'])
    H = len(template)
    path = flow['path']
    N = len(path)
    labels = flow['labels']
    qpos = kinds.index('Q')
    tpos = kinds.index('T')
    kpos = [i for i, c in enumerate(kinds) if c == 'K']
    dpos = [i for i, c in enumerate(kinds) if c == 'D']
    zpos = [i for i, c in enumerate(kinds) if c == 'Z']

    compressed = False
    if enabled:
        compressed = True
        for i in kpos:
            if header[i] != template[i]:
                compressed = False
                reason = 'mismatch'
                break
        else:
            if header[qpos] > 7:
                compressed = False
                reason = 'qos'
            else:
                reason = 'compressed'
    else:
        reason = 'disabled'
    mode = 'mpls' if compressed else 'ip'

    residue = bytes(header[i] for i in dpos)
    tc = header[qpos]
    wire = []
    ttl = header[tpos]
    delivered = None
    for link in range(N):
        if ttl == 0:
            break
        if compressed:
            word = (labels[link] << 12) | (tc << 9) | 0x100 | ttl
            wire.append(word.to_bytes(4, 'big').hex() + residue.hex() + payload.hex())
        else:
            h = bytearray(header)
            h[tpos] = ttl
            wire.append(h.hex() + payload.hex())
        if link < N - 1:
            # a switch receives this link with the current ttl
            if ttl <= 1:
                break
            ttl -= 1
    if len(wire) == N:
        if compressed:
            out = bytearray(H)
            for i in kpos:
                out[i] = template[i]
            for j, i in enumerate(dpos):
                out[i] = residue[j]
            for i in zpos:
                out[i] = 0
            out[qpos] = tc
            out[tpos] = ttl
            delivered = out.hex() + payload.hex()
        else:
            delivered = wire[-1]
    hops = 0
    for w in wire:
        hops += len(w) // 2
    return {'mode': mode, 'reason': reason, 'wire': wire,
            'delivered': delivered, 'byte_hops': hops}


def ref_replay(caps, flows_raw, events):
    flows = {}
    for f in flows_raw:
        flows[f['id']] = f
    tables = {n: {} for n in caps}
    enabled = set()
    results = []
