        op = ev['op']
        if op == 'put':
            f = flows[ev['flow']]
            node = ev['node']
            label = f['labels'][f['path'].index(node)]
            tbl = tables[node]
            if tbl.get(label) == f['id']:
                results.append({'status': 'ok'})
                continue
            busy = False
            for e in enabled:
                ef = flows[e]
                if node in ef['path']:
                    el = ef['labels'][ef['path'].index(node)]
                    if el == label:
                        busy = True
                        break
            if busy:
                results.append({'status': 'busy'})
                continue
            if label not in tbl and len(tbl) >= caps[node]:
                results.append({'status': 'full'})
                continue
            tbl[label] = f['id']
            results.append({'status': 'ok'})
        elif op == 'enable':
            f = flows[ev['flow']]
            ok = True
            for i, node in enumerate(f['path']):
                if tables[node].get(f['labels'][i]) != f['id']:
                    ok = False
                    break
            if ok:
                enabled.add(f['id'])
                results.append({'status': 'ok'})
            else:
                results.append({'status': 'unready'})
        elif op == 'disable':
            enabled.discard(ev['flow'])
            results.append({'status': 'ok'})
        elif op == 'reset':
            enabled.clear()
            results.append({'status': 'ok'})
        elif op == 'packet':
            f = flows[ev['flow']]
            results.append(ref_packet(f, ev['header'], ev['payload'],
                                      f['id'] in enabled))
        else:
            raise ValueError('bad op')
    tbl_out = []
    for node in sorted(tables):
        for label in sorted(tables[node]):
            tbl_out.append({'node': node, 'label': label,
                            'flow': tables[node][label]})
    return {'results': results, 'active': sorted(enabled), 'tables': tbl_out}
